def _evaluation_summary(eval_path, limit=12):
    """Summarize completed evaluations in generation order, including parent deltas."""
    if not os.path.isdir(eval_path):
        return "No readable prior-evaluation directory was found."

    generations = []
    for name in os.listdir(eval_path):
        match = re.fullmatch(r"gen_(initial|\d+)", name)
        if match and os.path.isdir(os.path.join(eval_path, name)):
            order = -1 if match.group(1) == "initial" else int(match.group(1))
            generations.append((order, name))

    records = []
    for _, generation in sorted(generations):
        generation_dir = os.path.join(eval_path, generation)
        try:
            with open(os.path.join(generation_dir, "metadata.json"), encoding="utf-8") as f:
                metadata = json.load(f)
        except (OSError, ValueError):
            metadata = {}
        if metadata.get("run_full_eval") is False:
            continue

        for root, _, files in os.walk(generation_dir):
            if "report.json" not in files:
                continue
            try:
                with open(os.path.join(root, "report.json"), encoding="utf-8") as f:
                    report = json.load(f)
            except (OSError, ValueError):
                continue
            metrics = {
                key: value for key, value in report.items()
                if isinstance(value, (int, float))
                and not isinstance(value, bool)
                and math.isfinite(value)
                and ("accuracy" in key.lower() or "score" in key.lower())
            }
            if not metrics:
                continue
            failed = report.get(
                "question_ids_failed", report.get("task_ids_failed", report.get("failed_ids", []))
            )
            records.append({
                "generation": generation,
                "parent": metadata.get("parent_genid"),
                "report": os.path.relpath(root, generation_dir),
                "metrics": metrics,
                "failed": failed if isinstance(failed, list) else [],
            })

    if not records:
        return "No completed evaluation reports with accuracy/score metrics were found."

    # Compare only reports with matching paths and metric names; different eval sets
    # or metrics should never be presented as directly comparable.
    scores = {}
    for record in records:
        for metric, value in record["metrics"].items():
            scores[(record["generation"], record["report"], metric)] = value

    lines = [
        "Completed prior evaluations (compare only matching report paths and metrics):",
        "Use these results to investigate generalizable improvements, not to memorize task IDs.",
    ]
    for record in records[-limit:]:
        scores_text = []
        for metric, value in record["metrics"].items():
            text = f"{metric}={value:.4g}"
            parent = record["parent"]
            parent_key = (f"gen_{parent}", record["report"], metric)
            if parent is not None and parent_key in scores:
                text += f" ({value - scores[parent_key]:+ .4g} vs parent)".replace("+ ", "+")
            scores_text.append(text)
        failed = record["failed"]
        failed_text = f"; failed IDs: {', '.join(map(str, failed[:12]))}" if failed else ""
        lines.append(
            f"- {record['generation']} (parent {record['parent']}), {record['report']}: "
            f"{', '.join(scores_text)}{failed_text}"
        )

    leaders = {}
    for record in records:
        for metric, value in record["metrics"].items():
            key = (record["report"], metric)
            if key not in leaders or value > leaders[key][0]:
                leaders[key] = (value, record)
    for (report_path, metric), (value, record) in sorted(leaders.items()):
        lines.append(
            f"- Best observed for {report_path} / {metric}: "
            f"{record['generation']} at {value:.4g}."
        )
    return "\n".join(lines)


